// Go's answer: data-locality and allocation discipline, not prefetch hints.
// Value slice beats []*T: the GC scans []T with no pointer, and it is contiguous.
type Row struct { A, B, C float64 }

func Sum(rows []Row) float64 {
    var s float64
    for i := range rows {      // contiguous, pointer-free: streams the cache
        s += rows[i].A + rows[i].B + rows[i].C
    }
    return s
}
